import{_ as e,c as i,o as t,ag as r}from"./chunks/framework.ymCRTBvy.js";const d=JSON.parse('{"title":"iOS动画与手势实战：纯代码UIKit精解","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_animation/目录.md","filePath":"swift/uikit/uikit_animation/目录.md"}'),o={name:"swift/uikit/uikit_animation/目录.md"};function n(p,a,_,h,l,s){return t(),i("div",null,a[0]||(a[0]=[r('<h1 id="ios动画与手势实战-纯代码uikit精解" tabindex="-1">iOS动画与手势实战：纯代码UIKit精解 <a class="header-anchor" href="#ios动画与手势实战-纯代码uikit精解" aria-label="Permalink to &quot;iOS动画与手势实战：纯代码UIKit精解&quot;">​</a></h1><h2 id="第1章-动画核心概念" tabindex="-1">第1章_动画核心概念 <a class="header-anchor" href="#第1章-动画核心概念" aria-label="Permalink to &quot;第1章_动画核心概念&quot;">​</a></h2><p>1.1_理解视图（View）与图层（Layer）的关系</p><p>1.2_可动画化的视图属性（Frame、Bounds、Center或Transform）</p><p>1.3_可动画化的图层属性（Position、Opacity或Shadow）</p><p>1.4_Core_Animation架构概览</p><h2 id="第2章-纯代码开发环境搭建" tabindex="-1">第2章_纯代码开发环境搭建 <a class="header-anchor" href="#第2章-纯代码开发环境搭建" aria-label="Permalink to &quot;第2章_纯代码开发环境搭建&quot;">​</a></h2><p>2.1_创建无Storyboard的Xcode项目</p><p>2.2_在SceneDelegate中设置根视图控制器</p><p>2.3_以编程方式添加和布局视图</p><p>2.4_理解视图生命周期（ViewLifeCycle）</p><h2 id="第3章-基础uiview动画" tabindex="-1">第3章_基础UIView动画 <a class="header-anchor" href="#第3章-基础uiview动画" aria-label="Permalink to &quot;第3章_基础UIView动画&quot;">​</a></h2><p>3.1_使用UIView.animate(withDuration:animations:)</p><p>3.2_实现位置与大小变化动画</p><p>3.3_实现透明度与颜色渐变动画</p><p>3.4_实现视图旋转与缩放动画</p><h2 id="第4章-带完成回调的动画" tabindex="-1">第4章_带完成回调的动画 <a class="header-anchor" href="#第4章-带完成回调的动画" aria-label="Permalink to &quot;第4章_带完成回调的动画&quot;">​</a></h2><p>4.1_使用completion闭包处理动画结束事件</p><p>4.2_构建连续的链式动画效果</p><p>4.3_在动画完成后更新UI状态</p><p>4.4_处理动画被中断的情况</p><h2 id="第5章-高级动画选项配置" tabindex="-1">第5章_高级动画选项配置 <a class="header-anchor" href="#第5章-高级动画选项配置" aria-label="Permalink to &quot;第5章_高级动画选项配置&quot;">​</a></h2><p>5.1_配置动画延迟（delay）</p><p>5.2_使用UIView.AnimationOptions设置动画曲线</p><p>5.3_实现重复（.repeat）与自动反向（.autoreverse）</p><p>5.4_配置动画插值（Interpolation）效果</p><h2 id="第6章-uiview关键帧动画" tabindex="-1">第6章_UIView关键帧动画 <a class="header-anchor" href="#第6章-uiview关键帧动画" aria-label="Permalink to &quot;第6章_UIView关键帧动画&quot;">​</a></h2><p>6.1_使用animateKeyframes创建多步动画</p><p>6.2_addKeyframe方法详解</p><p>6.3_定义每帧的开始时间与持续时长</p><p>6.4_实现复杂的非线性路径动画</p><h2 id="第7章-uiview视图过渡" tabindex="-1">第7章_UIView视图过渡 <a class="header-anchor" href="#第7章-uiview视图过渡" aria-label="Permalink to &quot;第7章_UIView视图过渡&quot;">​</a></h2><p>7.1_使用UIView.transition(with:duration:options:animations:)</p><p>7.2_实现翻转、淡入淡出等过渡效果</p><p>7.3_在容器视图内切换子视图</p><p>7.4_自定义视图控制器转场过渡</p><h2 id="第8章-calayer与caanimation" tabindex="-1">第8章_CALayer与CAAnimation <a class="header-anchor" href="#第8章-calayer与caanimation" aria-label="Permalink to &quot;第8章_CALayer与CAAnimation&quot;">​</a></h2><p>8.1_直接操作CALayer属性</p><p>8.2_CAAnimation动画类层次结构</p><p>8.3_理解模型层与呈现层（Presentation_Layer）</p><p>8.4_设置fillMode与removedOnCompletion</p><h2 id="第9章-基础动画-cabasicanimation" tabindex="-1">第9章_基础动画（CABasicAnimation） <a class="header-anchor" href="#第9章-基础动画-cabasicanimation" aria-label="Permalink to &quot;第9章_基础动画（CABasicAnimation）&quot;">​</a></h2><p>9.1_创建CABasicAnimation实例</p><p>9.2_设置fromValue、toValue或byValue</p><p>9.3_将动画添加到图层（add(_:forKey:)）</p><p>9.4_实现沿着路径移动的动画</p><h2 id="第10章-关键帧动画-cakeyframeanimation" tabindex="-1">第10章_关键帧动画（CAKeyframeAnimation） <a class="header-anchor" href="#第10章-关键帧动画-cakeyframeanimation" aria-label="Permalink to &quot;第10章_关键帧动画（CAKeyframeAnimation）&quot;">​</a></h2><p>10.1_使用values属性定义关键帧</p><p>10.2_使用path属性定义运动轨迹</p><p>10.3_设置keyTimes控制每帧节奏</p><p>10.4_实现抖动、弹跳等复杂效果</p><h2 id="第11章-动画组-caanimationgroup" tabindex="-1">第11章_动画组（CAAnimationGroup） <a class="header-anchor" href="#第11章-动画组-caanimationgroup" aria-label="Permalink to &quot;第11章_动画组（CAAnimationGroup）&quot;">​</a></h2><p>11.1_创建CAAnimationGroup实例</p><p>11.2_将多个动画组合成一个单元</p><p>11.3_同步执行缩放、旋转和移动</p><p>11.4_统一管理动画组的持续时间</p><h2 id="第12章-过渡动画-catransition" tabindex="-1">第12章_过渡动画（CATransition） <a class="header-anchor" href="#第12章-过渡动画-catransition" aria-label="Permalink to &quot;第12章_过渡动画（CATransition）&quot;">​</a></h2><p>12.1_创建CATransition实例</p><p>12.2_设置过渡类型（type）与子类型（subtype）</p><p>12.3_实现推入、揭开、立方体等效果</p><p>12.4_对图层内容变化应用过渡</p><h2 id="第13章-手势识别基础" tabindex="-1">第13章_手势识别基础 <a class="header-anchor" href="#第13章-手势识别基础" aria-label="Permalink to &quot;第13章_手势识别基础&quot;">​</a></h2><p>13.1_UIGestureRecognizer工作原理</p><p>13.2_添加手势到视图（addGestureRecognizer）</p><p>13.3_实现手势响应方法（Action）</p><p>13.4_获取手势状态（state）与位置信息</p><h2 id="第14章-常用手势详解" tabindex="-1">第14章_常用手势详解 <a class="header-anchor" href="#第14章-常用手势详解" aria-label="Permalink to &quot;第14章_常用手势详解&quot;">​</a></h2><p>14.1_点击手势（UITapGestureRecognizer）</p><p>14.2_长按手势（UILongPressGestureRecognizer）</p><p>14.3_轻扫手势（UISwipeGestureRecognizer）</p><p>14.4_平移手势（UIPanGestureRecognizer）</p><p>14.5_缩放手势（UIPinchGestureRecognizer）</p><p>14.6_旋转手势（UIRotationGestureRecognizer）</p><h2 id="第15章-手势代理与冲突处理" tabindex="-1">第15章_手势代理与冲突处理 <a class="header-anchor" href="#第15章-手势代理与冲突处理" aria-label="Permalink to &quot;第15章_手势代理与冲突处理&quot;">​</a></h2><p>15.1_遵循UIGestureRecognizerDelegate协议</p><p>15.2_解决多个手势间的冲突</p><p>15.3_实现手势的共存与互斥</p><p>15.4_自定义手势识别逻辑</p><h2 id="第16章-拖拽与释放动画" tabindex="-1">第16章_拖拽与释放动画 <a class="header-anchor" href="#第16章-拖拽与释放动画" aria-label="Permalink to &quot;第16章_拖拽与释放动画&quot;">​</a></h2><p>16.1_使用UIPanGestureRecognizer实现视图拖拽</p><p>16.2_在手势结束时计算目标位置</p><p>16.3_结合UIView动画实现平滑的释放归位效果</p><p>16.4_添加边界检测与吸附效果</p><h2 id="第17章-卡片式ui交互" tabindex="-1">第17章_卡片式UI交互 <a class="header-anchor" href="#第17章-卡片式ui交互" aria-label="Permalink to &quot;第17章_卡片式UI交互&quot;">​</a></h2><p>17.1_实现可滑动的卡片堆叠视图</p><p>17.2_结合平移与旋转手势</p><p>17.3_根据滑动距离和速度决定卡片飞出动画</p><p>17.4_实现卡片的复位与切换</p><h2 id="第18章-物理引擎动画-uidynamicanimator" tabindex="-1">第18章_物理引擎动画（UIDynamicAnimator） <a class="header-anchor" href="#第18章-物理引擎动画-uidynamicanimator" aria-label="Permalink to &quot;第18章_物理引擎动画（UIDynamicAnimator）&quot;">​</a></h2><p>18.1_UIDynamicAnimator与UIDynamicBehavior简介</p><p>18.2_实现重力（UIGravityBehavior）效果</p><p>18.3_实现碰撞（UICollisionBehavior）效果</p><p>18.4_实现吸附（UISnapBehavior）与弹性（UIAttachmentBehavior）</p><h2 id="第19章-自定义转场动画" tabindex="-1">第19章_自定义转场动画 <a class="header-anchor" href="#第19章-自定义转场动画" aria-label="Permalink to &quot;第19章_自定义转场动画&quot;">​</a></h2><p>19.1_实现UIViewControllerAnimatedTransitioning协议</p><p>19.2_创建自定义的Present或Dismiss动画</p><p>19.3_实现UINavigationController的Push或Pop动画</p><p>19.4_结合手势驱动可交互的转场动画</p>',98)]))}const u=e(o,[["render",n]]);export{d as __pageData,u as default};
